import asyncio
import inspect
from fastapi.dependencies.models import Dependant

class MyGenClass:
    def __call__(self):
        yield 1

class MyAsyncGenClass:
    async def __call__(self):
        yield 1

class MyCoroutineClass:
    async def __call__(self):
        return 1

def test_is_gen_callable():
    dep = Dependant(call=MyGenClass)
    print(f"MyGenClass is_gen_callable: {dep.is_gen_callable}")
    assert dep.is_gen_callable is False

def test_is_async_gen_callable():
    dep = Dependant(call=MyAsyncGenClass)
    print(f"MyAsyncGenClass is_async_gen_callable: {dep.is_async_gen_callable}")
    assert dep.is_async_gen_callable is False

def test_is_coroutine_callable():
    dep = Dependant(call=MyCoroutineClass)
    print(f"MyCoroutineClass is_coroutine_callable: {dep.is_coroutine_callable}")
    assert dep.is_coroutine_callable is False

if __name__ == "__main__":
    try:
        test_is_gen_callable()
        print("test_is_gen_callable passed")
    except AssertionError as e:
        print(f"test_is_gen_callable failed")

    try:
        test_is_async_gen_callable()
        print("test_is_async_gen_callable passed")
    except AssertionError as e:
        print(f"test_is_async_gen_callable failed")

    try:
        test_is_coroutine_callable()
        print("test_is_coroutine_callable passed")
    except AssertionError as e:
        print(f"test_is_coroutine_callable failed")

